const keepSellerTaxProfileUnderReview = `-- name: KeepSellerTaxProfileUnderReview :execrows
UPDATE seller_tax_profiles
SET review_note = $1,
    -- 只在 review_note **真的改變**時推進（#3089 第 11 項）：同值重寫不算一次新備註，
    -- 否則 A03 上那則備註的時間會隨每一次無關的審核動作往前跳。
    review_note_at = CASE WHEN review_note IS DISTINCT FROM $1
                          THEN $2 ELSE review_note_at END,
    updated_at = $2,
    version = version + 1
WHERE id = $3
  AND review_status = 'UNDER_REVIEW'
  AND version = $4
`

type KeepSellerTaxProfileUnderReviewParams struct {
	ReviewNote      *string            `db:"review_note" json:"review_note"`
	Now             pgtype.Timestamptz `db:"now" json:"now"`
	ID              int64              `db:"id" json:"id"`
	ExpectedVersion int64              `db:"expected_version" json:"expected_version"`
}

// T16 UNDER_REVIEW → UNDER_REVIEW（**自轉移**，ADM 決策 KEEP_UNDER_REVIEW）。
// 存在理由：ADM 需要一個「我看過了、但還不能決定」的可稽核動作，否則那件案子會被反覆重看
// 而沒有任何痕跡，而唯一能留痕的做法會是誤用 REQUEST_SUPPLEMENT（那會真的去催賣家補件）。
// ⚠️ **不改任何時鐘欄位**：pending_valid_until 不重算、extension_count 不動。
//
//	留痕落在 invoice_status_history（from_status = to_status），不在本表。
//
// version 照常 +1：它是一次業務操作，且同一列被 ADM 寫的次數有上界（§5.3.6 的判準是
// 「同一列被寫的次數有沒有上界」，不是「誰觸發的」）。
func (q *Queries) KeepSellerTaxProfileUnderReview(ctx context.Context, arg KeepSellerTaxProfileUnderReviewParams) (int64, error) {
	result, err := q.db.Exec(ctx, keepSellerTaxProfileUnderReview,
		arg.ReviewNote,
		arg.Now,
		arg.ID,
		arg.ExpectedVersion,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const listTaxReviewsForAdmin = `-- name: ListTaxReviewsForAdmin :many
SELECT p.id, p.issuer_id, p.review_status, p.claimed_obligation, p.entity_tax_type, p.legal_name, p.tax_id, p.responsible_person, p.business_address, p.address_city, p.address_district, p.default_tax_category, p.evidence_object_keys, p.attestation_version, p.attested_at, p.attested_by_account_id, p.submitted_at, p.pending_valid_until, p.extension_count, p.pending_order_limit_count, p.pending_order_limit_amount, p.pending_order_count, p.pending_order_amount, p.review_note, p.review_note_at, p.approved_at, p.cooldown_until, p.approval_valid_until, p.recheck_reason, p.receipt_authorized_at, p.receipt_consent_version, p.receipt_approval_basis_key, p.receipt_approval_basis_asset_id, p.violation_window_days, p.violation_threshold, p.suspension_days, p.version, p.created_at, p.updated_at,
       i.issuer_ref_id AS issuer_ref_id,
       (SELECT COUNT(*)::bigint FROM invoice_complaints c
         WHERE c.issuer_id = p.issuer_id
           AND c.status = ANY($1::text[])) AS open_complaint_count
FROM seller_tax_profiles p
JOIN invoice_issuers i ON i.id = p.issuer_id
WHERE (COALESCE(cardinality($2::text[]), 0) = 0
       OR p.review_status = ANY($2::text[]))
  AND (NOT $3::boolean
       OR (p.pending_valid_until IS NOT NULL
           AND p.pending_valid_until <= $4::timestamptz))
  AND (NOT $5::boolean OR p.extension_count >= 1)
  AND ($6::text = ''
       OR p.tax_id = $6::text
       OR i.issuer_ref_id::text = $6::text
       OR p.legal_name ILIKE '%' || $6::text || '%')
ORDER BY p.created_at ASC, p.id ASC
LIMIT $8 OFFSET $7
`

type ListTaxReviewsForAdminParams struct {
	OpenComplaintStatuses []string           `db:"open_complaint_statuses" json:"open_complaint_statuses"`
	StatusFilters         []string           `db:"status_filters" json:"status_filters"`
	NearDeadlineOnly      bool               `db:"near_deadline_only" json:"near_deadline_only"`
	NearDeadlineBefore    pgtype.Timestamptz `db:"near_deadline_before" json:"near_deadline_before"`
	ExtendedOnly          bool               `db:"extended_only" json:"extended_only"`
	Keyword               string             `db:"keyword" json:"keyword"`
	RowOffset             int32              `db:"row_offset" json:"row_offset"`
	RowLimit              int32              `db:"row_limit" json:"row_limit"`
}

type ListTaxReviewsForAdminRow struct {
	SellerTaxProfile   SellerTaxProfile `db:"seller_tax_profile" json:"seller_tax_profile"`
	IssuerRefID        int64            `db:"issuer_ref_id" json:"issuer_ref_id"`
	OpenComplaintCount int64            `db:"open_complaint_count" json:"open_complaint_count"`
}

// 端點 38（A02 稅務審核佇列）。吃 idx_stp_review_queue。
//
// 🔴 六個 `filter` **不是互斥分頁**（§6.1.12）：`NEAR_DEADLINE` 與 `EXTENDED` 是
//
//	「前四狀態之一 AND 額外條件」的**交集視圖** ⇒ 三個條件在 SQL 裡是 **AND**
//	（呼叫端送 status_filters = 前四狀態 ＋ 對應旗標），不是 OR。
//	做成互斥會讓案件從原分頁消失；而六個 filter 的筆數加總 ≠ 總筆數 ⇒
//	**A02 的 UI 不得顯示「合計」**，也不得用「總數 − 其他五頁」倒算任何一頁。
//
// `open_complaint_count` 供 riskFlags 的 `OPEN_COMPLAINTS` 判定（其餘兩個 flag 的
//
//	資料源不在本服務，見呼叫端）。
//
// keyword 比對 legal_name／tax_id／**store_id**（＝ invoice_issuers.issuer_ref_id）。
//
// 🔴 store_id 這一格是 2026-09-04 補的（#3089 第 16 項）：本註解原本寫著
//
//	「依店名搜尋要由呼叫端先解析成 store_id 再進來」，而述詞裡**根本沒有
//	store_id 的比對** —— 呼叫端就算解析出來了也搜不到。
//	ADM 的搜尋框逐字寫「搜尋店名 / store_id」，於是照螢幕上的字去搜必然 0 筆。
//	issuer_ref_id 就在本句已經 JOIN 的那張表上，零跨服務成本。
//	轉成 text 比對而不是把 keyword 轉 bigint：搜尋框收的是自由文字，
//	非數字輸入應該是「查無」而不是 22P02（invalid input syntax）＝ HTTP 500。
//
// ⚠️ **store_name（店名）仍然不在本服務**（seller-service 才有）⇒ 那一格搜不了，
//
//	ADM 的文案已同步改成「法定名稱 / 統編 / store_id」，不再承諾做不到的事。
func (q *Queries) ListTaxReviewsForAdmin(ctx context.Context, arg ListTaxReviewsForAdminParams) ([]ListTaxReviewsForAdminRow, error) {
	rows, err := q.db.Query(ctx, listTaxReviewsForAdmin,
		arg.OpenComplaintStatuses,
		arg.StatusFilters,
		arg.NearDeadlineOnly,
		arg.NearDeadlineBefore,
		arg.ExtendedOnly,
		arg.Keyword,
		arg.RowOffset,
		arg.RowLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListTaxReviewsForAdminRow{}
	for rows.Next() {
		var i ListTaxReviewsForAdminRow
		if err := rows.Scan(
			&i.SellerTaxProfile.ID,
			&i.SellerTaxProfile.IssuerID,
			&i.SellerTaxProfile.ReviewStatus,
			&i.SellerTaxProfile.ClaimedObligation,
			&i.SellerTaxProfile.EntityTaxType,
			&i.SellerTaxProfile.LegalName,
			&i.SellerTaxProfile.TaxID,
			&i.SellerTaxProfile.ResponsiblePerson,
			&i.SellerTaxProfile.BusinessAddress,
			&i.SellerTaxProfile.AddressCity,
			&i.SellerTaxProfile.AddressDistrict,
			&i.SellerTaxProfile.DefaultTaxCategory,
			&i.SellerTaxProfile.EvidenceObjectKeys,
			&i.SellerTaxProfile.AttestationVersion,
			&i.SellerTaxProfile.AttestedAt,
			&i.SellerTaxProfile.AttestedByAccountID,
			&i.SellerTaxProfile.SubmittedAt,
			&i.SellerTaxProfile.PendingValidUntil,
			&i.SellerTaxProfile.ExtensionCount,
			&i.SellerTaxProfile.PendingOrderLimitCount,
			&i.SellerTaxProfile.PendingOrderLimitAmount,
			&i.SellerTaxProfile.PendingOrderCount,
			&i.SellerTaxProfile.PendingOrderAmount,
			&i.SellerTaxProfile.ReviewNote,
			&i.SellerTaxProfile.ReviewNoteAt,
			&i.SellerTaxProfile.ApprovedAt,
			&i.SellerTaxProfile.CooldownUntil,
			&i.SellerTaxProfile.ApprovalValidUntil,
			&i.SellerTaxProfile.RecheckReason,
			&i.SellerTaxProfile.ReceiptAuthorizedAt,
			&i.SellerTaxProfile.ReceiptConsentVersion,
			&i.SellerTaxProfile.ReceiptApprovalBasisKey,
			&i.SellerTaxProfile.ReceiptApprovalBasisAssetID,
			&i.SellerTaxProfile.ViolationWindowDays,
			&i.SellerTaxProfile.ViolationThreshold,
			&i.SellerTaxProfile.SuspensionDays,
			&i.SellerTaxProfile.Version,
			&i.SellerTaxProfile.CreatedAt,
			&i.SellerTaxProfile.UpdatedAt,
			&i.IssuerRefID,
			&i.OpenComplaintCount,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const rejectSellerTaxProfile = `-- name: RejectSellerTaxProfile :execrows
UPDATE seller_tax_profiles
SET review_status = 'REJECTED',
    cooldown_until = $1,
    review_note = $2,
    -- 只在 review_note **真的改變**時推進（#3089 第 11 項）：同值重寫不算一次新備註，
    -- 否則 A03 上那則備註的時間會隨每一次無關的審核動作往前跳。
    review_note_at = CASE WHEN review_note IS DISTINCT FROM $2
                          THEN $3 ELSE review_note_at END,
    updated_at = $3,
    version = version + 1
WHERE id = $4
  AND review_status IN ('UNDER_REVIEW', 'SELF_ISSUE_PENDING')
  AND version = $5
`

type RejectSellerTaxProfileParams struct {
	CooldownUntil   *time.Time         `db:"cooldown_until" json:"cooldown_until"`
	ReviewNote      *string            `db:"review_note" json:"review_note"`
	Now             pgtype.Timestamptz `db:"now" json:"now"`
	ID              int64              `db:"id" json:"id"`
	ExpectedVersion int64              `db:"expected_version" json:"expected_version"`
}

// T09 UNDER_REVIEW／SELF_ISSUE_PENDING → REJECTED（ADM 決策 REJECT）。
// cooldown_until = now + 7 天由呼叫端傳入；它是 T01 第二形態（ResetSellerTaxProfileToDraft）
// 那個守衛讀的欄位——少寫這一欄，被駁回的賣家可以立刻無限重送。
func (q *Queries) RejectSellerTaxProfile(ctx context.Context, arg RejectSellerTaxProfileParams) (int64, error) {
	result, err := q.db.Exec(ctx, rejectSellerTaxProfile,
		arg.CooldownUntil,
		arg.ReviewNote,
		arg.Now,
		arg.ID,
		arg.ExpectedVersion,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const requestSellerTaxProfileSupplement = `-- name: RequestSellerTaxProfileSupplement :execrows
UPDATE seller_tax_profiles
SET review_status = 'SUPPLEMENT_REQUIRED',
    review_note = $1,
    -- 只在 review_note **真的改變**時推進（#3089 第 11 項）：同值重寫不算一次新備註，
    -- 否則 A03 上那則備註的時間會隨每一次無關的審核動作往前跳。
    review_note_at = CASE WHEN review_note IS DISTINCT FROM $1
                          THEN $2 ELSE review_note_at END,
    updated_at = $2,
    version = version + 1
WHERE id = $3
  AND review_status = 'UNDER_REVIEW'
  AND version = $4
`

type RequestSellerTaxProfileSupplementParams struct {
	ReviewNote      *string            `db:"review_note" json:"review_note"`
	Now             pgtype.Timestamptz `db:"now" json:"now"`
	ID              int64              `db:"id" json:"id"`
	ExpectedVersion int64              `db:"expected_version" json:"expected_version"`
}

// T05 UNDER_REVIEW → SUPPLEMENT_REQUIRED（ADM 決策 REQUEST_SUPPLEMENT）。
// chk_stp_pending_window 把 SUPPLEMENT_REQUIRED 與 SELF_ISSUE_PENDING 一起納入
// 「必須有 submitted_at ＋ pending_valid_until」⇒ 若上游沒走過 T02（例：ADM 直接建列），
// 本句會 23514 而不是靜默寫壞。
func (q *Queries) RequestSellerTaxProfileSupplement(ctx context.Context, arg RequestSellerTaxProfileSupplementParams) (int64, error) {
	result, err := q.db.Exec(ctx, requestSellerTaxProfileSupplement,
		arg.ReviewNote,
		arg.Now,
		arg.ID,
		arg.ExpectedVersion,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const resetSellerTaxProfileToDraft = `-- name: ResetSellerTaxProfileToDraft :execrows
UPDATE seller_tax_profiles
SET review_status = 'DRAFT',
    submitted_at = NULL,
    pending_valid_until = NULL,
    extension_count = 0,
    cooldown_until = NULL,
    updated_at = $1,
    version = version + 1
WHERE id = $2
  AND review_status IN ('REJECTED', 'EXPIRED')
  AND (cooldown_until IS NULL OR cooldown_until <= $1)
`

type ResetSellerTaxProfileToDraftParams struct {
	Now pgtype.Timestamptz `db:"now" json:"now"`
	ID  int64              `db:"id" json:"id"`
}

// T01 的第二種形態（REJECTED／EXPIRED → DRAFT，冷卻屆滿後重新申請）。
// 守衛 `cooldown_until IS NULL OR cooldown_until <= now` 就是決策 C3 的 7 天冷卻，寫在述詞裡
// ——寫在應用層的 if 會在併發重送時同時通過兩次。
// 回 DRAFT 時清空上一輪的時鐘欄：submitted_at／pending_valid_until 留著會讓 T02 算出的新
// 60 天窗口與舊值並存，而 chk_stp_pending_window 只檢查非空、不檢查新鮮度。
func (q *Queries) ResetSellerTaxProfileToDraft(ctx context.Context, arg ResetSellerTaxProfileToDraftParams) (int64, error) {
	result, err := q.db.Exec(ctx, resetSellerTaxProfileToDraft, arg.Now, arg.ID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const resubmitSellerTaxProfileSupplement = `-- name: ResubmitSellerTaxProfileSupplement :execrows
UPDATE seller_tax_profiles
SET review_status = 'UNDER_REVIEW',
    evidence_object_keys = $1,
    updated_at = $2,
    version = version + 1
WHERE id = $3
  AND review_status = 'SUPPLEMENT_REQUIRED'
  AND version = $4
`

type ResubmitSellerTaxProfileSupplementParams struct {
	EvidenceObjectKeys json.RawMessage    `db:"evidence_object_keys" json:"evidence_object_keys"`
	Now                pgtype.Timestamptz `db:"now" json:"now"`
	ID                 int64              `db:"id" json:"id"`
	ExpectedVersion    int64              `db:"expected_version" json:"expected_version"`
}

// T06 SUPPLEMENT_REQUIRED → UNDER_REVIEW（賣家補齊）。
// 與 T12／T13／T15 分開是刻意的：那三條是 ADM 入口，合併會讓賣家的「補齊」按鈕
// 也能把 EXPIRED／REVOKED 的 profile 推回審核中，繞過 T12「ADM 明示且必填理由」。
func (q *Queries) ResubmitSellerTaxProfileSupplement(ctx context.Context, arg ResubmitSellerTaxProfileSupplementParams) (int64, error) {
	result, err := q.db.Exec(ctx, resubmitSellerTaxProfileSupplement,
		arg.EvidenceObjectKeys,
		arg.Now,
		arg.ID,
		arg.ExpectedVersion,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const revokeSellerTaxProfile = `-- name: RevokeSellerTaxProfile :execrows
UPDATE seller_tax_profiles
SET review_status = 'REVOKED',
    review_note = $1,
    -- 只在 review_note **真的改變**時推進（#3089 第 11 項）：同值重寫不算一次新備註，
    -- 否則 A03 上那則備註的時間會隨每一次無關的審核動作往前跳。
    review_note_at = CASE WHEN review_note IS DISTINCT FROM $1
                          THEN $2 ELSE review_note_at END,
    updated_at = $2,
    version = version + 1
WHERE id = $3
  AND review_status IN ('APPROVED_INVOICE_REQUIRED', 'APPROVED_INVOICE_EXEMPT')
  AND version = $4
`

type RevokeSellerTaxProfileParams struct {
	ReviewNote      *string            `db:"review_note" json:"review_note"`
	Now             pgtype.Timestamptz `db:"now" json:"now"`
	ID              int64              `db:"id" json:"id"`
	ExpectedVersion int64              `db:"expected_version" json:"expected_version"`
}

// T14 APPROVED_* → REVOKED（ADM 撤銷資格）。
// 守衛是「必填理由 ＋ confirmed=true 二次確認 ＋ 完整稽核」，**不是雙人確認**——全案唯一的
// 雙人機制是端點 54／55 的人工解鎖。二次確認發生在端點層，DB 這一側只有 expectedVersion CAS。
// 撤銷後新訂單走 LEGACY_MANUAL；已付款未開票的訂單維持付款當下的快照模式（不回溯）。
func (q *Queries) RevokeSellerTaxProfile(ctx context.Context, arg RevokeSellerTaxProfileParams) (int64, error) {
	result, err := q.db.Exec(ctx, revokeSellerTaxProfile,
		arg.ReviewNote,
		arg.Now,
		arg.ID,
		arg.ExpectedVersion,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const submitSellerTaxProfile = `-- name: SubmitSellerTaxProfile :execrows
UPDATE seller_tax_profiles
SET review_status = 'SUBMITTED',
    submitted_at = $1,
    pending_valid_until = $2,
    attestation_version = $3,
    attested_at = $1,
    -- #3031：三元組一起寫。條款是自然人的意思表示，只有版本與時間舉不出簽署主體。
    attested_by_account_id = $4,
    updated_at = $1,
    version = version + 1
WHERE id = $5
  AND review_status = 'DRAFT'
  AND version = $6
`

type SubmitSellerTaxProfileParams struct {
	Now                 *time.Time `db:"now" json:"now"`
	PendingValidUntil   *time.Time `db:"pending_valid_until" json:"pending_valid_until"`
	AttestationVersion  *string    `db:"attestation_version" json:"attestation_version"`
	AttestedByAccountID *int64     `db:"attested_by_account_id" json:"attested_by_account_id"`
	ID                  int64      `db:"id" json:"id"`
	ExpectedVersion     int64      `db:"expected_version" json:"expected_version"`
}

// T02 DRAFT → SUBMITTED。**單一時鐘**：submitted_at ＝ 60 天期限的唯一起算點（決策 C4），
// pending_valid_until = submitted_at + 60 天由呼叫端算好傳入（測試要能注入 clock）。
// 兩欄必須同一句寫：chk_stp_pending_window 對 SELF_ISSUE_PENDING／SUPPLEMENT_REQUIRED
// 要求兩者皆非空，而那兩個狀態的**唯一**上游就是本列（T04／T05）——這裡少寫，下游當場 23514。
//
// 🔴 **attestation_version／attested_at 也在同一句**（裁決 C，2026-08-31）。
//
//	不變式：**送審成功 ⇒ 條款必已簽**。做成同一句而不是「同一個交易內兩句」是刻意的：
//	兩句版本的原子性靠呼叫端記得包 tx，而那是一次重構就會掉的保證；同一句版本則是
//	「rows=1 ⇒ 五欄全寫」，任何呼叫順序都拆不開。
//	⚠️ **兩欄無條件寫，不留 COALESCE／CASE 的退化分支**：那個形狀原本是要把「參數
//	不小心傳空」變成「保留舊值」，實測的結果卻是**該列被寫成 SUBMITTED 而兩個條款欄
//	留 NULL，且呼叫端收到 ok=true** —— 一個沒有簽署記錄的送審，而且靜默。現在改成
//	直接寫入，配合 schema 的三條 CHECK（chk_stp_attestation_pair／
//	_version_nonblank／_attested_when_committed），空字串或 NULL 一律 23514 當場失敗、
//	一列不寫。**吵一次好過寫出一列查不到憑據的資料**（同 RequestSellerTaxProfileSupplement
//	那一句「23514 而不是靜默寫壞」的取捨）。
//	⚠️ **不動 review_status 的 allowed-from（仍是 DRAFT）**。
func (q *Queries) SubmitSellerTaxProfile(ctx context.Context, arg SubmitSellerTaxProfileParams) (int64, error) {
	result, err := q.db.Exec(ctx, submitSellerTaxProfile,
		arg.Now,
		arg.PendingValidUntil,
		arg.AttestationVersion,
		arg.AttestedByAccountID,
		arg.ID,
		arg.ExpectedVersion,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const updateSellerTaxProfileDraft = `-- name: UpdateSellerTaxProfileDraft :execrows
UPDATE seller_tax_profiles
SET claimed_obligation = $1,
    entity_tax_type = $2,
    legal_name = $3,
    tax_id = $4,
    responsible_person = $5,
    business_address = $6,
    -- #3031：三段地址分開存。business_address 是串接後的完整地址（AMEGO 送件與
    -- 單行顯示用），city／district 是回程要還原到表單的兩格——只存串接結果的話
    -- joinAddress 折起來就拆不回去，賣家重新編輯時那兩格是空的。
    address_city = $7,
    address_district = $8,
    default_tax_category = $9,
    evidence_object_keys = $10,
    review_note = $11,
    -- 只在 review_note **真的改變**時推進（#3089 第 11 項）：同值重寫不算一次新備註，
    -- 否則 A03 上那則備註的時間會隨每一次無關的審核動作往前跳。
    review_note_at = CASE WHEN review_note IS DISTINCT FROM $11
                          THEN $12 ELSE review_note_at END,
    updated_at = $12,
    version = version + 1
WHERE id = $13
  AND review_status = 'DRAFT'
  AND version = $14
`

type UpdateSellerTaxProfileDraftParams struct {
	ClaimedObligation  string             `db:"claimed_obligation" json:"claimed_obligation"`
	EntityTaxType      *string            `db:"entity_tax_type" json:"entity_tax_type"`
	LegalName          *string            `db:"legal_name" json:"legal_name"`
	TaxID              *string            `db:"tax_id" json:"tax_id"`
	ResponsiblePerson  *string            `db:"responsible_person" json:"responsible_person"`
	BusinessAddress    *string            `db:"business_address" json:"business_address"`
	AddressCity        *string            `db:"address_city" json:"address_city"`
	AddressDistrict    *string            `db:"address_district" json:"address_district"`
	DefaultTaxCategory int16              `db:"default_tax_category" json:"default_tax_category"`
	EvidenceObjectKeys json.RawMessage    `db:"evidence_object_keys" json:"evidence_object_keys"`
	ReviewNote         *string            `db:"review_note" json:"review_note"`
	Now                pgtype.Timestamptz `db:"now" json:"now"`
	ID                 int64              `db:"id" json:"id"`
	ExpectedVersion    int64              `db:"expected_version" json:"expected_version"`
}

// 端點 18 的草稿存檔（不是狀態轉移，status 不動）。
// ⚠️ evidence_object_keys 在**這裡**就已經是換發後的 objectKey（端點 18 在寫本表之前把
//
//	evidenceStagedTokens[] 換成 objectKey，§6.1.7），T02 的守衛讀的正是本欄 ⇒ 只上傳沒存草稿
//	就直接送審，那個守衛必然不成立。
//
// allowed-from 只有 DRAFT：已送審的資料由 ADM 流程處理，賣家不得就地改內容。
func (q *Queries) UpdateSellerTaxProfileDraft(ctx context.Context, arg UpdateSellerTaxProfileDraftParams) (int64, error) {
	result, err := q.db.Exec(ctx, updateSellerTaxProfileDraft,
		arg.ClaimedObligation,
		arg.EntityTaxType,
		arg.LegalName,
		arg.TaxID,
		arg.ResponsiblePerson,
		arg.BusinessAddress,
		arg.AddressCity,
		arg.AddressDistrict,
		arg.DefaultTaxCategory,
		arg.EvidenceObjectKeys,
		arg.ReviewNote,
		arg.Now,
		arg.ID,
		arg.ExpectedVersion,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
